const LEAD = [[0,"REST",0,1],[16,"A",0,1],[48,"A",0,1],[80,"A",0,1],[112,"REST",0,1],[208,"REST",0,1],[224,"A",0,1],[256,"REST",0,1],[288,"A",1,1],[320,"A",1,1],[352,"A",0,2]]
